    def minimumPushes(self, word: str) -> int:
        result = 0
        hash_map = {}
        number = 2

        # Mapping letters to keys
        for char in word:
            if number > 9:
                number = 2
            if number not in hash_map:
                hash_map[number] = []
            hash_map[number].append(char)
            number += 1

        # Calculate pushes
        for char in word:
            for num in range(2, 10):
                if char in hash_map[num]:
                    result += (hash_map[num].index(char) + 1)
                    break

        return result

