class Solution:
    def canSortArray(self, nums: List[int]) -> bool:
        def count_set_bits(x):
            return bin(x).count('1')

        # Create a list of tuples (set_bits_count, original_value)
        set_bits_groups = {}

        for num in nums:
            set_bits = count_set_bits(num)
            if set_bits not in set_bits_groups:
                set_bits_groups[set_bits] = []
            set_bits_groups[set_bits].append(num)

        # Sort each group
        for key in set_bits_groups:
            set_bits_groups[key].sort()

        # Reconstruct the array based on the original order
        reconstructed = []
        for num in nums:
            set_bits = count_set_bits(num)
            reconstructed.append(set_bits_groups[set_bits].pop(0))

        # Check if the reconstructed array is sorted
        return reconstructed == sorted(nums)

