class Solution:
    def minMovesToCaptureTheQueen(self, a: int, b: int, c: int, d: int, e: int, f: int) -> int:
        directions_rook = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        directions_bishop = [(1, 1), (1, -1), (-1, 1), (-1, -1)]

        def is_in_bounds(x, y):
            return 1 <= x <= 8 and 1 <= y <= 8

        def can_capture(x, y):
            return (x == e and y == f)

        queue = deque([(a, b, c, d, 0)])  # (rook_x, rook_y, bishop_x, bishop_y, moves)
        visited = set()
        visited.add((a, b, c, d))

        while queue:
            rook_x, rook_y, bishop_x, bishop_y, moves = queue.popleft()

            if can_capture(rook_x, rook_y) or can_capture(bishop_x, bishop_y):
                return moves

            # Generate rook moves
            for dx, dy in directions_rook:
                x, y = rook_x, rook_y
                while True:
                    x += dx
                    y += dy
                    if not is_in_bounds(x, y):
                        break
                    if (x, y) == (bishop_x, bishop_y):  # Can't jump over bishop
                        break
                    if (x, y) == (e, f):  # Capture queen
                        return moves + 1
                    if (x, y) != (rook_x, rook_y):
                        new_state = (x, y, bishop_x, bishop_y)
                        if new_state not in visited:
                            visited.add(new_state)
                            queue.append((x, y, bishop_x, bishop_y, moves + 1))

            # Generate bishop moves
            for dx, dy in directions_bishop:
                x, y = bishop_x, bishop_y
                while True:
                    x += dx
                    y += dy
                    if not is_in_bounds(x, y):
                        break
                    if (x, y) == (rook_x, rook_y):  # Can't jump over rook
                        break
                    if (x, y) == (e, f):  # Capture queen
                        return moves + 1
                    if (x, y) != (bishop_x, bishop_y):
                        new_state = (rook_x, rook_y, x, y)
                        if new_state not in visited:
                            visited.add(new_state)
                            queue.append((rook_x, rook_y, x, y, moves + 1))

        return -1  # Should not reach here as per problem statement

