class Solution:
    def maximumLength(self, s: str) -> int:
        count = {}
        n = len(s)
        i = 0

        while i < n:
            char = s[i]
            start = i

            # Count the length of the segment of identical characters
            while i < n and s[i] == char:
                i += 1

            length = i - start

            # Generate special substrings and update counts
            for l in range(1, length + 1):
                substring = char * l
                if substring in count:
                    count[substring] += 1
                else:
                    count[substring] = 1

        # Filter substrings that occur at least thrice
        valid_lengths = [len(sub) for sub, cnt in count.items() if cnt >= 3]

        # Return -1 if no valid substrings found
        if not valid_lengths:
            return -1

        # Return the maximum length of valid substrings
        return max(valid_lengths)

