class Solution:
    def maximumLength(self, s: str) -> int:
        ans = 0
        n = len(s)
        freq = {}

        # Identify special substrings
        i = 0
        while i < n:
            count = 1
            while i + 1 < n and s[i] == s[i + 1]:
                count += 1
                i += 1

            # Count special substrings of lengths from 1 to count
            for length in range(1, count + 1):
                substring = s[i] * length
                if substring in freq:
                    freq[substring] += 1
                else:
                    freq[substring] = 1

            i += 1

        # Check for the longest special substring that occurs at least 3 times
        for substring, occurrence in freq.items():
            if occurrence >= 3:
                ans = max(ans, len(substring))

        return ans if ans > 0 else -1

