class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        count = 0
        left = 0
        frequency = defaultdict(int)

        for right in range(len(nums)):
            frequency[nums[right]] += 1

            # Update the maximum element in the current window
            max_element = max(frequency.keys())

            # While the count of the max element is less than k, move the left pointer
            while frequency[max_element] < k:
                frequency[nums[left]] -= 1
                if frequency[nums[left]] == 0:
                    del frequency[nums[left]]
                left += 1

                # Update max_element if necessary
                if frequency:
                    max_element = max(frequency.keys())
                else:
                    break

            # If the count of max_element is at least k, count valid subarrays
            if frequency[max_element] >= k:
                count += (right - left + 1)

