class Solution:
    def lexicographicallySmallestArray(self, nums: List[int], limit: int) -> List[int]:
        n = len(nums)
        graph = defaultdict(list)

        # Build the graph
        for i in range(n):
            for j in range(i + 1, n):
                if abs(nums[i] - nums[j]) <= limit:
                    graph[i].append(j)
                    graph[j].append(i)

        visited = [False] * n
        result = nums[:]

        def bfs(start):
            queue = deque([start])
            component = []
            while queue:
                node = queue.popleft()
                if not visited[node]:
                    visited[node] = True
                    component.append(node)
                    for neighbor in graph[node]:
                        if not visited[neighbor]:
                            queue.append(neighbor)
            return component

        # Find connected components and sort them
        for i in range(n):
            if not visited[i]:
                component = bfs(i)
                indices = sorted(component)
                values = sorted(nums[index] for index in component)
                for idx, value in zip(indices, values):
                    result[idx] = value

        return result

