class Solution:
    def findChampion(self, n: int, edges: List[List[int]]) -> int:
        # Step 1: Initialize the graph and in-degree array
        graph = [[] for _ in range(n)]
        in_degree = [0] * n

        # Step 2: Build the graph and in-degree array
        for u, v in edges:
            graph[u].append(v)
            in_degree[v] += 1

        # Step 3: Initialize the queue with nodes having in-degree of 0
        queue = deque()
        for i in range(n):
            if in_degree[i] == 0:
                queue.append(i)

        # Step 4: Process the graph
        champion = -1
        while queue:
            if len(queue) > 1:
                return -1  # More than one team with in-degree 0

            champion = queue.popleft()

            for neighbor in graph[champion]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        # Step 5: Check if we have a unique champion
        if champion != -1 and all(in_degree[i] > 0 for i in range(n) if i != champion):
            return champion

        return -1

