            for subset in itertools.combinations(range(n), r):
                active_set = set(range(n)) - set(subset)

                if not active_set:
                    valid_sets_count += 1
                    continue

                if len(active_set) == 1:
                    valid_sets_count += 1
                    continue

                distances = dijkstra(next(iter(active_set)), active_set)

                if all(distances[node] <= maxDistance for node in active_set):
                    valid_sets_count += 1

        return valid_sets_count

