class Solution:
    def countSubMultisets(self, nums: List[int], l: int, r: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (r + 1)
        dp[0] = 1

        counts = Counter(nums)

        for a, c in counts.items():
            for k in range(r, -1, -1):
                for m in range(1, c + 1):
                    if k >= a * m:
                        dp[k] = (dp[k] + dp[k - a * m]) % MOD

        return sum(dp[l:r + 1]) % MOD

