        n = len(nums)
        IDX = [0] * 32
        ans = [0] * n

        for x in nums:
            for i in range(32):
                if (x >> i) & 1:
                    ans[IDX[i]] += (1 << i)
                    IDX[i] += 1

        res = 0
        mod = 10**9 + 7

        for i in range(k):
            res = (res + ans[i] * ans[i]) % mod

        return res

