import math

class Solution:
    def maximumSum(self, nums: List[int]) -> int:

        def prime_factors(n):
            factors = defaultdict(int)
            for i in range(2, int(math.sqrt(n)) + 1):
                while n % i == 0:
                    factors[i] += 1
                    n //= i
            if n > 1:
                factors[n] += 1
            return factors

        groups = defaultdict(int)

        for num in nums:
            factors = prime_factors(num)
            # Create a key based on the parity of the prime factor exponents
            parity_key = tuple(sorted(p for p, exp in factors.items() if exp % 2 != 0))
            groups[parity_key] += num

        return max(groups.values(), default=0)

