class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        count = Counter(nums)
        ops = 0

        # If the sum of nums is less than target, return -1
        if sum(nums) < target:
            return -1

        total = 0

        # Try to form the target from the largest to smallest
        for num in sorted(count.keys(), reverse=True):
            while count[num] > 0 and total < target:
                if total + num <= target:
                    total += num
                    count[num] -= 1
                else:
                    break

            # If we reached the target, return the number of operations
            if total == target:
                return ops

            # If we still need more, we need to split the current number
            while count[num] > 0 and total < target:
                count[num] -= 1
                ops += 1
                count[num // 2] += 2

        return -1 if total < target else ops

