class Solution:
    def countPalindromePaths(self, parent: List[int], s: str) -> int:
        lookup = defaultdict(list)
        total = 0

        for index, p in enumerate(parent):
            if p != -1:
                lookup[p].append((index, ord(s[index]) - ord('a')))

        counter = Counter()

        def go(node, mask):
            nonlocal total
            total += counter[mask]
            for i in range(26):
                total += counter[mask ^ (1 << i)]
            counter[mask] += 1

            for nxt, c in lookup[node]:
                go(nxt, mask ^ (1 << c))

        go(0, 0)
        return total

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        forbidden_set = set(forbidden)
        left = 0
        max_length = 0

        for right in range(len(word)):
            for length in range(1, 11):  # Check substrings of length 1 to 10
                if right - length + 1 >= left:
                    if word[right - length + 1:right + 1] in forbidden_set:
                        left = right - length + 2  # Move left pointer past the forbidden substring
                        break
            max_length = max(max_length, right - left + 1)

        return max_length

